import 'package:flutter/material.dart';
import 'package:auto_size_text/auto_size_text.dart';

class BasicAutoSizeExample extends StatelessWidget {
  const BasicAutoSizeExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // 기본 AutoSizeText
            Container(
              width: 200,
              height: 50,
              color: Colors.grey[200],
              child: const AutoSizeText(
                '이 텍스트는 컨테이너 크기에 맞게 자동으로 조절됩니다',
                style: TextStyle(fontSize: 30),
                maxLines: 1,
              ),
            ),
            const SizedBox(height: 20),

            // 최소 크기 설정
            Container(
              width: 200,
              height: 50,
              color: Colors.blue[100],
              child: const AutoSizeText(
                '최소 크기가 12로 제한된 텍스트입니다',
                style: TextStyle(fontSize: 30),
                minFontSize: 12,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:auto_size_text/auto_size_text.dart';

class SizeControlExample extends StatelessWidget {
  const SizeControlExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // minFontSize: 최소 크기 제한
        Container(
          width: 150,
          height: 40,
          color: Colors.amber[100],
          child: const AutoSizeText(
            '최소 10px까지만 줄어듭니다',
            style: TextStyle(fontSize: 24),
            minFontSize: 10,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ),
        const SizedBox(height: 16),

        // maxFontSize: 최대 크기 제한
        Container(
          width: 300,
          height: 100,
          color: Colors.green[100],
          child: const AutoSizeText(
            '짧음',
            style: TextStyle(fontSize: 100),
            maxFontSize: 40, // 아무리 공간이 넓어도 40px 이하
          ),
        ),
        const SizedBox(height: 16),

        // stepGranularity: 크기 조절 단위
        Container(
          width: 200,
          height: 50,
          color: Colors.purple[100],
          child: const AutoSizeText(
            '2px 단위로 크기가 조절됩니다',
            style: TextStyle(fontSize: 30),
            stepGranularity: 2, // 28, 26, 24... 순으로 줄어듦
            minFontSize: 10,
          ),
        ),
        const SizedBox(height: 16),

        // presetFontSizes: 미리 정의된 크기만 사용
        Container(
          width: 200,
          height: 50,
          color: Colors.orange[100],
          child: const AutoSizeText(
            '24, 18, 14, 10 중에서만 선택됩니다',
            presetFontSizes: [24, 18, 14, 10],
          ),
        ),
      ],
    );
  }
}

