// 메뉴 버튼 그룹 예제
class MenuButtonGroup extends StatelessWidget {
  const MenuButtonGroup({super.key});

  @override
  Widget build(BuildContext context) {
    final menuGroup = AutoSizeGroup();
    final menus = ['홈', '설정', '프로필', '알림 센터'];

    return Row(
      children: menus.map((menu) {
        return Expanded(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 4),
            child: ElevatedButton(
              onPressed: () {},
              child: AutoSizeText(
                menu,
                group: menuGroup,
                maxLines: 1,
                style: const TextStyle(fontSize: 16),
              ),
            ),
          ),
        );
      }).toList(),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:auto_size_text/auto_size_text.dart';

class RichTextExample extends StatelessWidget {
  const RichTextExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // Rich text 기본
        Container(
          width: 250,
          height: 60,
          color: Colors.grey[200],
          child: AutoSizeText.rich(
            TextSpan(
              children: [
                const TextSpan(
                  text: '할인가: ',
                  style: TextStyle(color: Colors.black),
                ),
                TextSpan(
                  text: '₩15,000',
                  style: TextStyle(
                    color: Colors.red[700],
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const TextSpan(
                  text: ' (30% 할인)',
                  style: TextStyle(
                    color: Colors.grey,
                    fontSize: 14,
                  ),
                ),
              ],
            ),
            style: const TextStyle(fontSize: 24),
            maxLines: 1,
          ),
        ),
        const SizedBox(height: 20),

        // 태그와 함께 사용
        Container(
          width: 200,
          height: 40,
          color: Colors.blue[50],
          child: AutoSizeText.rich(
            TextSpan(
              children: [
                WidgetSpan(
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 6,
                      vertical: 2,
                    ),
                    margin: const EdgeInsets.only(right: 8),
                    decoration: BoxDecoration(
                      color: Colors.blue,
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: const Text(
                      'NEW',
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 10,
                      ),
                    ),
                  ),
                ),
                const TextSpan(text: '신상품이 입고되었습니다'),
              ],
            ),
            style: const TextStyle(fontSize: 18),
            maxLines: 1,
          ),
        ),
      ],
    );
  }
}

// 실제 사용 예: 상품 카드
class ProductCard extends StatelessWidget {
  final String name;
  final int price;
  final int? discountPrice;
  final String? badge;

  const ProductCard({
    super.key,
    required this.name,
    required this.price,
    this.discountPrice,
    this.badge,
  });

  @override
  Widget build(BuildContext context) {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 상품명 (자동 크기 조절)
            SizedBox(
              height: 48,
              child: AutoSizeText(
                name,
                style: const TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                ),
                maxLines: 2,
                minFontSize: 14,
              ),
            ),
            const SizedBox(height: 8),
            // 가격 정보
            AutoSizeText.rich(
              TextSpan(
                children: [
                  if (badge != null)
                    WidgetSpan(
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 4,
                          vertical: 2,
                        ),
                        margin: const EdgeInsets.only(right: 6),
                        decoration: BoxDecoration(
                          color: Colors.red,
                          borderRadius: BorderRadius.circular(2),
                        ),
                        child: Text(
                          badge!,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 10,
                          ),
                        ),
                      ),
                    ),
                  if (discountPrice != null) ...[
                    TextSpan(
                      text: '₩${price.toString().replaceAllMapped(
                        RegExp(r'(\d)(?=(\d{3})+(?!\d))'),
                        (m) => '${m[1]},',
                      )} ',
                      style: const TextStyle(
                        color: Colors.grey,
                        decoration: TextDecoration.lineThrough,
                        fontSize: 14,
                      ),
                    ),
                    TextSpan(
                      text: '₩${discountPrice.toString().replaceAllMapped(
                        RegExp(r'(\d)(?=(\d{3})+(?!\d))'),
                        (m) => '${m[1]},',
                      )}',
                      style: const TextStyle(
                        color: Colors.red,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ] else
                    TextSpan(
                      text: '₩${price.toString().replaceAllMapped(
                        RegExp(r'(\d)(?=(\d{3})+(?!\d))'),
                        (m) => '${m[1]},',
                      )}',
                      style: const TextStyle(fontWeight: FontWeight.bold),
                    ),
                ],
              ),
              style: const TextStyle(fontSize: 16),
              maxLines: 1,
              minFontSize: 12,
            ),
          ],
        ),
      ),
    );
  }
}
